```java
import java.util.Scanner;

public class ExamSheet {
    // Marks (out of 100) of 4 students in 3 subjects of an imagined school
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int[][] m = new int[4][3];
        for (int i = 0; i < 4; i++)
            for (int j = 0; j < 3; j++)
                m[i][j] = sc.nextInt();
        int best = 0, topper = 0;
        for (int i = 0; i < 4; i++) {
            int total = 0;
            for (int j = 0; j < 3; j++)
                total = total + m[i][j];
            double pc = total / 3.0;
            System.out.println("Student " + (i + 1) + ": total = " + total + ", percentage = " + pc);
            if (total > best) {
                best = total;
                topper = i + 1;
            }
        }
        for (int j = 0; j < 3; j++) {
            int sum = 0;
            for (int i = 0; i < 4; i++)
                sum = sum + m[i][j];
            System.out.println("Subject " + (j + 1) + " average = " + (sum / 4.0));
        }
        System.out.println("Topper: Student " + topper + " with " + best);
    }
}
```

